from collections import Counter
class Solution:
    def minCostEqualize(self, nums1, nums2):
        ca, cb = Counter(nums1), Counter(nums2)
        cost = 0
        for v in set(ca) | set(cb):
            p, q = ca.get(v, 0), cb.get(v, 0)
            if (p + q) % 2:
                return -1
            cost += max(0, (p + q) // 2 - p)
        return cost

