class Solution {
public:
    int minCostEqualize(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int, long long> ca, cb;
        for (int x : nums1) ca[x]++;
        for (int x : nums2) cb[x]++;
        long long cost = 0;
        for (auto& [v, p] : ca) {
            long long q = cb.count(v) ? cb[v] : 0;
            if ((p + q) % 2) return -1;
            cost += max(0LL, (p + q) / 2 - p);
        }
        for (auto& [v, q] : cb)
            if (!ca.count(v)) {
                if (q % 2) return -1;
                cost += q / 2;
            }
        return (int) cost;
    }
};

