class Solution {
    public int minCostEqualize(int[] nums1, int[] nums2) {
        Map<Integer, Integer> ca = new HashMap<>(), cb = new HashMap<>();
        for (int x : nums1) ca.merge(x, 1, Integer::sum);
        for (int x : nums2) cb.merge(x, 1, Integer::sum);
        long cost = 0;
        for (Map.Entry<Integer, Integer> e : ca.entrySet()) {
            int p = e.getValue();
            int q = cb.getOrDefault(e.getKey(), 0);
            if ((p + q) % 2 != 0) return -1;
            cost += Math.max(0, (p + q) / 2 - p);
        }
        for (Map.Entry<Integer, Integer> e : cb.entrySet())
            if (!ca.containsKey(e.getKey())) {
                if (e.getValue() % 2 != 0) return -1;
                cost += e.getValue() / 2;
            }
        return (int) cost;
    }
}

