class Solution:
    def minCostEqualize(self, nums1, nums2):
        n = len(nums1)
        best = -1
        for mask in range(1 << n):
            a = [nums2[i] if mask >> i & 1 else nums1[i] for i in range(n)]
            b = [nums1[i] if mask >> i & 1 else nums2[i] for i in range(n)]
            if sorted(a) == sorted(b):
                c = bin(mask).count('1')
                if best == -1 or c < best:
                    best = c
        return best

